sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.loading = false;
  c.searchTerm = "";
  c.statusFilter = "";

  c.getStatusClass = function(status) {
    var classes = {
      "draft": "label-default",
      "in_progress": "label-info",
      "clarification_requested": "label-warning",
      "submitted": "label-primary",
      "admin_review": "label-info",
      "build_ready": "label-success",
      "completed": "label-success"
    };
    return classes[status] || "label-default";
  };

  c.filterApplications = function() {
    c.loading = true;
    c.server.get({
      action: "filter",
      status: c.statusFilter,
      search: c.searchTerm
    }).then(function(r) {
      c.data.applications = r.data.applications;
      c.data.totalCount = r.data.totalCount;
      c.loading = false;
    }, function() {
      c.loading = false;
    });
  };

  c.openApplication = function(app) {
    window.location.href = "?id=appready_questionnaire&app_id=" + app.sys_id;
  };
};

sp_widget.css:
.ibar-filter-row {
  margin-top: 12px;
}
.ibar-clickable-row {
  cursor: pointer;
}
.ibar-clickable-row:hover {
  background-color: $background-secondary;
}
.ibar-progress-sm {
  height: 6px;
  margin-bottom: 4px;
  border-radius: 3px;
}
.ibar-empty-state {
  padding: 48px 24px;
}
.ibar-empty-icon {
  font-size: 48px;
  display: block;
  margin-bottom: 16px;
  opacity: 0.35;
  color: $text-muted;
}
@keyframes ibar-spin-animation {
  to { transform: rotate(360deg); }
}
.ibar-spin {
  animation: ibar-spin-animation 0.8s linear infinite;
  font-size: 24px;
  color: $brand-primary;
}

sp_widget.script:
(function() {
  data.applications = [];
  data.message = "";
  data.totalCount = 0;

  try {
    if (input && input.action === "filter") {
      loadApplications(input.status || "", input.search || "");
      return;
    }

    loadApplications("", "");
  } catch (e) {
    gs.error("IBAR Application Grid widget error: " + e.message);
    data.message = "An error occurred loading the application inventory.";
  }

  function loadApplications(statusFilter, searchFilter) {
    var appGr = new GlideRecord("x_1433041_identi_0_application");
    appGr.addQuery("active", true);

    if (statusFilter) {
      appGr.addQuery("questionnaire_status", statusFilter);
    }
    if (searchFilter) {
      var orCondition = appGr.addQuery("name", "CONTAINS", searchFilter);
      orCondition.addOrCondition("number", "CONTAINS", searchFilter);
    }

    appGr.orderByDesc("sys_updated_on");
    appGr.setLimit(100);
    appGr.query();

    data.totalCount = appGr.getRowCount();

    while (appGr.next()) {
      data.applications.push({
        sys_id: appGr.getUniqueValue(),
        name: appGr.getValue("name"),
        number: appGr.getValue("number"),
        client: appGr.getDisplayValue("client"),
        status: appGr.getValue("questionnaire_status"),
        status_display: appGr.getDisplayValue("questionnaire_status"),
        completion_percent: parseInt(appGr.getValue("completion_percent")) || 0,
        last_saved_at: appGr.getDisplayValue("last_saved_at"),
        clarification_status: appGr.getDisplayValue("clarification_status"),
        missing_items_count: parseInt(appGr.getValue("missing_items_count")) || 0
      });
    }
  }
})();
